import type { DefaultOptions, FilterDataStructure } from 'models/Filters';

import { BaseFilterDataTransformer } from '../BaseFilterDataTransformer';

export interface BrandPowerResultsData {
  periods: DefaultOptions;
}

export interface BrandPowerResultsApiData extends FilterDataStructure {
  brand_power_results: BrandPowerResultsData;
}

export class BrandPowerResultsFilterDataTransformer extends BaseFilterDataTransformer<BrandPowerResultsApiData> {
  private readonly data: BrandPowerResultsApiData;

  constructor(data: BrandPowerResultsApiData) {
    super();
    this.data = data;
  }

  static transform(data: unknown): FilterDataStructure {
    if (!this.isNewFormat(data)) {
      return {};
    }

    const mapper = new BrandPowerResultsFilterDataTransformer(
      data as BrandPowerResultsApiData,
    );
    return mapper.transform();
  }

  static isNewFormat(data: unknown): boolean {
    return data !== null && typeof data === 'object';
  }

  toFlat(): BrandPowerResultsData & FilterDataStructure {
    const { periods } = this.data.brand_power_results;
    delete this.data.brand_power_results;

    return {
      ...this.data,
      periods,
    };
  }
}
